import React, { useState, useEffect } from 'react';
import AgentGrid from './AgentGrid';
import AgentModal from './AgentModal';

function MainContent({
  currentUser,
  onLogout,
  agents,
  purchasedMap,
  accessStatus,
  logs,
  commHistory,
  authToken,
  apiBase,
  onLoadAgents,
  onLoadLogs,
  onLoadHistory
}) {
  const [activeTab, setActiveTab] = useState('marketplace');
  const [directAgentId, setDirectAgentId] = useState(null);

  // Check URL for direct agent access (without exposing tokens in URL)
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const agentId = params.get('agent');
    if (agentId) {
      setDirectAgentId(agentId);
      // Clean up URL to remove any exposed tokens/keys
      window.history.replaceState({}, '', window.location.pathname);
    }
  }, []);

  return (
    <div className="app-container">
      <header className="header">
        <h1>🤖 Agent Marketplace</h1>
        <div className="user-info">
          <span>Logged in as: <strong>{currentUser}</strong></span>
          <button className="logout-btn" onClick={onLogout}>
            Logout
          </button>
        </div>
      </header>

      <main className="main-content">
        <div className="tabs">
          <button
            className={`tab-btn ${activeTab === 'marketplace' ? 'active' : ''}`}
            onClick={() => setActiveTab('marketplace')}
          >
            💼 Marketplace
          </button>
        </div>

        <div className={`tab-content ${activeTab === 'marketplace' ? 'active' : ''}`}>
          <AgentGrid
            agents={agents}
            purchasedMap={purchasedMap}
            accessStatus={accessStatus}
            authToken={authToken}
            apiBase={apiBase}
            onLoadAgents={onLoadAgents}
          />
        </div>

        <div className={`tab-content ${activeTab === 'mcp-tools' ? 'active' : ''}`}>
          <MCPToolsGrid
            authToken={authToken}
            apiBase={apiBase}
          />
        </div>

        <div className={`tab-content ${activeTab === 'a2a' ? 'active' : ''}`}>
          <A2APanel
            agents={agents}
            commHistory={commHistory}
            authToken={authToken}
            apiBase={apiBase}
            onLoadHistory={onLoadHistory}
          />
        </div>

        <div className={`tab-content ${activeTab === 'logs' ? 'active' : ''}`}>
          <LogsPanel
            logs={logs}
            authToken={authToken}
            apiBase={apiBase}
            onLoadLogs={onLoadLogs}
          />
        </div>
      </main>

      {directAgentId && agents.length > 0 && (
        <AgentModal
          agent={agents.find(a => a.id === directAgentId)}
          purchased={purchasedMap && purchasedMap[directAgentId]}
          accessStatus={accessStatus[directAgentId] || {}}
          authToken={authToken}
          apiBase={apiBase}
          onClose={() => {
            setDirectAgentId(null);
            window.history.pushState({}, '', window.location.pathname);
          }}
          onLoadAgents={onLoadAgents}
        />
      )}
    </div>
  );
}

export default MainContent;
